using System.Reflection;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Rivet;

/// <summary>
/// Marks a record as an UNDISCRIMINATED union wrapper: at most one of its
/// optional properties is set, and on the wire the value is the BARE variant —
/// never the wrapper object. The OpenAPI emitter renders these as a
/// <c>oneOf</c> of the property types, and (being a JsonConverterAttribute)
/// serialization unwraps/rewraps to match, so the runtime and the emitted
/// spec tell the same story. Generated by the OpenAPI importer for
/// primitive/mixed <c>oneOf</c> schemas that have no discriminator.
/// </summary>
[AttributeUsage(AttributeTargets.Class | AttributeTargets.Struct)]
public sealed class RivetUnionAttribute : JsonConverterAttribute
{
    public override JsonConverter? CreateConverter(Type typeToConvert) =>
        (JsonConverter?)
            Activator.CreateInstance(
                typeof(RivetUnionJsonConverter<>).MakeGenericType(typeToConvert)
            );
}

/// <summary>
/// Serializes a [RivetUnion] wrapper as its single non-null variant value;
/// deserializes by matching the JSON kind against the variant property types
/// in declaration order. Wrappers are positional records whose parameters
/// mirror their properties (the shape the importer generates).
/// </summary>
internal sealed class RivetUnionJsonConverter<T> : JsonConverter<T>
{
    private static readonly PropertyInfo[] _variantProperties = RivetUnionVariants.Of(typeof(T));

    // The importer generates positional records: one constructor whose parameters
    // correspond 1:1 (by name, case-insensitively) with the variant properties.
    private static readonly ConstructorInfo _constructor = typeof(T)
        .GetConstructors()
        .OrderByDescending(candidate => candidate.GetParameters().Length)
        .First();

    private static readonly ParameterInfo[] _parameters = _constructor.GetParameters();

    public override T? Read(
        ref Utf8JsonReader reader,
        Type typeToConvert,
        JsonSerializerOptions options
    )
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var element = document.RootElement;

        foreach (var property in _variantProperties)
        {
            if (!KindMatches(element, property.PropertyType))
            {
                continue;
            }

            object? value;
            try
            {
                value = element.Deserialize(property.PropertyType, options);
            }
            catch (JsonException)
            {
                continue;
            }

            return Construct(property, value);
        }

        throw new JsonException(
            $"Value does not match any variant of union wrapper '{typeof(T).Name}'."
        );
    }

    public override void Write(Utf8JsonWriter writer, T value, JsonSerializerOptions options)
    {
        if (
            value is not null
            && RivetUnionVariants.Written(_variantProperties, value) is { } variant
        )
        {
            JsonSerializer.Serialize(writer, variant.Value, variant.DeclaredType, options);
            return;
        }

        writer.WriteNullValue();
    }

    private static bool KindMatches(JsonElement element, Type propertyType)
    {
        var underlying = Nullable.GetUnderlyingType(propertyType) ?? propertyType;

        if (underlying == typeof(string))
        {
            return element.ValueKind == JsonValueKind.String;
        }

        if (underlying == typeof(bool))
        {
            return element.ValueKind is JsonValueKind.True or JsonValueKind.False;
        }

        if (underlying.IsPrimitive || underlying == typeof(decimal))
        {
            return element.ValueKind == JsonValueKind.Number;
        }

        // Complex variants: object/array shapes; let Deserialize decide.
        return element.ValueKind is JsonValueKind.Object or JsonValueKind.Array;
    }

    private static T Construct(PropertyInfo matched, object? value) =>
        (T)
            _constructor.Invoke(
                _parameters
                    .Select(parameter =>
                        string.Equals(
                            parameter.Name,
                            matched.Name,
                            StringComparison.OrdinalIgnoreCase
                        )
                            ? value
                            : null
                    )
                    .ToArray()
            );
}

/// <summary>
/// The variant rule <see cref="RivetUnionJsonConverter{T}"/> writes by, shared with what
/// reads a wrapper the way it's written (<see cref="RivetExtensionDataKeys"/>), so the two
/// can't drift.
/// </summary>
internal static class RivetUnionVariants
{
    /// <summary>A wrapper's variants: every public readable instance property, in order.</summary>
    public static PropertyInfo[] Of(Type union) =>
        [
            .. union
                .GetProperties(BindingFlags.Public | BindingFlags.Instance)
                .Where(property => property.CanRead),
        ];

    /// <summary>
    /// The variant <paramref name="wrapper"/> is written as, and the type it's written as: its
    /// first non-null variant, as its declared property type. Null when no variant is set, and
    /// the wrapper is written as null.
    /// </summary>
    public static (object Value, Type DeclaredType)? Written(
        IEnumerable<PropertyInfo> variants,
        object wrapper
    )
    {
        foreach (var property in variants)
        {
            if (property.GetValue(wrapper) is { } variant)
            {
                return (variant, property.PropertyType);
            }
        }

        return null;
    }
}
